"""Stage 93: the binary analysis chapter (docs/59, generated by tools/analyze_binary_docs.py) is current, the ROM is the one of the manifest, the facts it states hold, and every opcode the program uses is a documented 6502 opcode."""
import hashlib
import os
import sys
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
sys.path.insert(0, os.path.join(ROOT, "tools"))
import analyze_binary_docs as B  # noqa: E402
import disasm6502 as D  # noqa: E402

DOC = os.path.join(ROOT, "docs", "59-binary-analysis.md")


class Binary(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.f = B.facts()

    def test_the_chapter_is_current(self):
        with open(DOC, encoding="utf-8", newline="") as fh:
            have = fh.read().replace("\r\n", "\n")
        self.assertEqual(have, B.doc(), "regenerate: python -I tools/analyze_binary_docs.py --doc docs/59-binary-analysis.md")

    def test_the_rom_is_the_one_of_the_manifest(self):
        data = B.read_rom()
        self.assertEqual(len(data), 8192)
        self.assertEqual(hashlib.sha256(data).hexdigest(), B.manifest()["original/Pac-Man.rom"][0])

    def test_code_and_data_account_for_every_byte_once(self):
        f = self.f
        cov = bytearray(8192)
        for a, v in f["ins"].items():
            for i in range(v[0]):
                cov[a - 0xA000 + i] += 1
        for lo, size, kind, name, note in f["data_regions"]:
            for x in range(lo, lo + size):
                cov[x - 0xA000] += 1
        self.assertEqual(sorted(set(cov)), [1], "every byte of the ROM is code or data, exactly once")
        self.assertEqual((len(f["ins"]), f["code"], f["data_bytes"], len(f["data_regions"])), (2925, 5946, 2246, 79))
        self.assertEqual((f["code_lo"], f["code_hi"]), (0xA386, 0xBAC0))

    def test_every_opcode_used_is_a_documented_one_and_the_counts_add_up(self):
        f = self.f
        self.assertTrue(all(o in D.OPCODES for o in f["opcodes"]))
        self.assertEqual(sum(f["opcodes"].values()), 2925)
        self.assertEqual((len(f["opcodes"]), len(f["mnemonics"])), (87, 49))
        for o, n in f["opcodes"].items():
            self.assertEqual(f["mnemonics"][D.OPCODES[o][0]] >= n, True)

    def test_the_routines_cover_the_code(self):
        f = self.f
        self.assertEqual(len(f["F"]), 81)
        self.assertEqual(sum(f["own_bytes"].values()), f["code"])
        self.assertEqual(sum(f["own_ins"].values()), len(f["ins"]))

    def test_the_machine_it_touches(self):
        f = self.f
        self.assertEqual(len(f["regs"]), 34)
        self.assertFalse(any(0xD300 <= a <= 0xD3FF for a in f["regs"]), "the PIA is never touched")
        self.assertEqual(f["os_calls"], [0xE45C, 0xE462])
        self.assertEqual(f["header"], [0x86, 0xA3, 0x00, 0x04, 0xB4, 0xA6])


if __name__ == "__main__":
    unittest.main()
